/* 04_catalog_reports.sql - the approved data catalogue (with methodology), ready-made blocks and seeded templates.
   Generated by tools/gen_catalog_reports.py (edit that script, then re-run it); idempotent: clears these tables and reseeds them.

   Catalogue expressions are trusted SQL written by admins. The API's query compiler aggregates them over one of:
   - Performance: dp.vw_AccountDailyPerformance rows in the block's period, combined per day across the accounts in
     each group (value-weighted returns), with GroupStart/GroupEnd (first/last day in the group), AnnYears (years to
     annualise over; 1 = not annualised), Contribution (the group's share of the total's daily return), CumLog and RunMax.
   - Holdings: dp.fn_HoldingSnapshot(<period end>) rows.   - Exposure: dp.fn_ExposureSnapshot(<period end>) rows.
   Every query also carries a Series column (the period label), so weights are computed per series.

   Templates are made of pages: {id, title, group, locked, condition, sectionLabel, heading, layout, style, blocks}.
   Locked pages are required by compliance. A page or disclaimer with a condition (StructuredProducts, MultiCurrency,
   Advisory) applies only when the client context meets it. Disclaimer text always comes from src_content.Disclosure.
   Text blocks with a "narrative" brief are drafted by the Narrative Agent from the period's verified figures. */

USE WealthInsightsV10Db;
GO
SET NOCOUNT ON;
GO

DELETE FROM studio.OrchestrationStep;
DELETE FROM studio.OrchestrationRun;
DELETE FROM studio.ClientReport;
DELETE FROM studio.ReportVersion;
DELETE FROM studio.Report;
DELETE FROM studio.BlockPreset;
DELETE FROM studio.CatalogCombination;
DELETE FROM studio.CatalogDimension;
DELETE FROM studio.CatalogMeasure;
DECLARE @Reseed NVARCHAR(MAX) = N'';
SELECT @Reseed += N'DBCC CHECKIDENT (''studio.' + QUOTENAME(OBJECT_NAME(object_id)) + N''', RESEED, 0) WITH NO_INFOMSGS;'
FROM sys.identity_columns
WHERE OBJECT_SCHEMA_NAME(object_id) = N'studio' AND last_value IS NOT NULL;
EXEC sys.sp_executesql @Reseed;
GO

/* ---------- Measures ---------- */

INSERT studio.CatalogMeasure (MeasureKey, Label, Symbol, Format, Description, PerformanceExpr, HoldingsExpr, RequiresGroup, Cumulative, Methodology, MethodologyVersion, Owner, ApprovedOn, SortOrder) VALUES
 (N'market_value', N'Market value', N'Σ', N'currency',
  N'Closing market value at the end of the period (or of each month/quarter), in USD.',
  N'CAST(SUM(CASE WHEN ValueDate = GroupEnd THEN MarketValue END) AS DECIMAL(18,2))',
  N'SUM(MarketValue)', 0, 0,
  N'Sum of account valuations on the last business day of the period, converted to USD at that day''s FX rate. For holdings groupings: the month-end holdings snapshot on or before the period end.', N'1.1', N'Data office', '2026-09-01', 1),
 (N'opening_value', N'Opening value', N'Σ', N'currency',
  N'Market value at the close of the business day before the period (zero for accounts opened during it).',
  N'CAST(ISNULL(SUM(CASE WHEN ValueDate = GroupStart THEN PriorMarketValue END), 0) AS DECIMAL(18,2))',
  NULL, 0, 0,
  N'Sum of the prior-day USD valuations on the first business day of the period. Accounts funded during the period start at zero; their funding counts as a deposit.', N'2.0', N'Performance & analytics', '2026-09-01', 2),
 (N'investment_gain', N'Investment gain', N'Σ', N'currency',
  N'Change in value not explained by deposits and withdrawals.',
  N'CAST(SUM(CASE WHEN ValueDate = GroupEnd THEN MarketValue END) - ISNULL(SUM(CASE WHEN ValueDate = GroupStart THEN PriorMarketValue END), 0) - SUM(NetFlow) AS DECIMAL(18,2))',
  NULL, 0, 0,
  N'Closing value minus opening value minus net external flows, in USD. Includes income, price changes and currency effects, after fees.', N'2.0', N'Performance & analytics', '2026-09-01', 3),
 (N'return_twr', N'Return (TWR)', N'%', N'percent',
  N'Time-weighted return in USD; several accounts are combined by value. Annualised for standard periods longer than a year.',
  N'CAST(POWER(EXP(SUM(LOG(1.0 + DailyReturn))), 1.0 / MAX(AnnYears)) - 1 AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Daily returns (USD, after fees) are combined across accounts weighted by each account''s prior-day value, then chained geometrically. Periods over one year in the standard-period table are annualised. Removes the effect of the size and timing of flows.', N'1.1', N'Performance & analytics', '2026-09-01', 4),
 (N'mwr', N'Return (MWR)', N'%', N'percent',
  N'Money-weighted return (Modified Dietz) in USD: reflects the timing and size of deposits and withdrawals.',
  N'CAST(POWER(1.0 + ((SUM(CASE WHEN ValueDate = GroupEnd THEN MarketValue END) - ISNULL(SUM(CASE WHEN ValueDate = GroupStart THEN PriorMarketValue END), 0) - SUM(NetFlow)) / NULLIF(ISNULL(SUM(CASE WHEN ValueDate = GroupStart THEN PriorMarketValue END), 0) + SUM(NetFlow * DATEDIFF(DAY, ValueDate, GroupEnd) / (DATEDIFF(DAY, GroupStart, GroupEnd) + 1.0)), 0)), 1.0 / MAX(AnnYears)) - 1 AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Modified Dietz: (closing value - opening value - net flows) / (opening value + flows weighted by the share of the period remaining after each flow). Calculated at account, entity and household level on the reported holdings; structured products are valued as single holdings (no look-through).', N'2.0', N'Performance & analytics', '2026-09-01', 5),
 (N'benchmark_return', N'Benchmark return', N'%', N'percent',
  N'Return of the benchmark over the same days (blended by value for several accounts).',
  N'CAST(POWER(EXP(SUM(LOG(1.0 + BenchmarkReturn))), 1.0 / MAX(AnnYears)) - 1 AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Each account''s benchmark daily return, combined across accounts with the same value weights as the portfolio return, then chained.', N'1.1', N'Performance & analytics', '2026-09-01', 6),
 (N'excess_return', N'Excess return', N'%', N'percent',
  N'Return (TWR) minus benchmark return.',
  N'CAST((POWER(EXP(SUM(LOG(1.0 + DailyReturn))), 1.0 / MAX(AnnYears)) - 1) - (POWER(EXP(SUM(LOG(1.0 + BenchmarkReturn))), 1.0 / MAX(AnnYears)) - 1) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Arithmetic difference between the time-weighted return and the benchmark return over the same period.', N'1.1', N'Performance & analytics', '2026-09-01', 7),
 (N'contribution', N'Contribution to return', N'%', N'percent',
  N'How much of the household''s return came from each account or entity (percentage points).',
  N'CAST(SUM(Contribution) AS DECIMAL(12,8))',
  NULL, 1, 0,
  N'Sum over the days of the period of the group''s share of the total prior-day value times its daily return. Contributions add up to the sum of the total''s daily returns; the small difference to the compounded return is the linking residual.', N'2.0', N'Performance & analytics', '2026-09-01', 8),
 (N'return_local', N'Return in local currency', N'%', N'percent',
  N'Time-weighted return in each account''s own currency, before currency effects.',
  N'CAST(POWER(EXP(SUM(LOG(1.0 + LocalDailyReturn))), 1.0 / MAX(AnnYears)) - 1 AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'As Return (TWR), but from valuations in the account''s own currency. For USD accounts it equals the USD return.', N'2.0', N'Performance & analytics', '2026-09-01', 9),
 (N'fx_effect', N'Currency effect', N'%', N'percent',
  N'USD return minus local-currency return: the effect of exchange-rate movements.',
  N'CAST((POWER(EXP(SUM(LOG(1.0 + DailyReturn))), 1.0 / MAX(AnnYears)) - 1) - (POWER(EXP(SUM(LOG(1.0 + LocalDailyReturn))), 1.0 / MAX(AnnYears)) - 1) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Difference between the time-weighted return in USD and in the account''s own currency over the same days, using daily closing FX rates.', N'2.0', N'Performance & analytics', '2026-09-01', 10),
 (N'net_flows', N'Net flows', N'Σ', N'currency',
  N'Deposits minus withdrawals in the period (initial funding counts as a deposit).',
  N'SUM(NetFlow)',
  NULL, 0, 0,
  N'Sum of external deposits less withdrawals, converted to USD at each day''s FX rate.', N'1.1', N'Data office', '2026-09-01', 11),
 (N'deposits', N'Deposits', N'Σ', N'currency',
  N'Total deposits in the period, including the initial funding of new accounts.',
  N'SUM(Deposits)',
  NULL, 0, 0,
  N'Sum of external deposits (and initial funding of accounts opened in the period), converted to USD at each day''s FX rate.', N'1.1', N'Data office', '2026-09-01', 12),
 (N'withdrawals', N'Withdrawals', N'Σ', N'currency',
  N'Total withdrawals in the period (positive number).',
  N'SUM(Withdrawals)',
  NULL, 0, 0,
  N'Sum of external withdrawals, converted to USD at each day''s FX rate.', N'1.1', N'Data office', '2026-09-01', 13),
 (N'fees', N'Fees', N'Σ', N'currency',
  N'Advisory fees charged in the period.',
  N'SUM(Fees)',
  NULL, 0, 0,
  N'Sum of advisory fees debited to the accounts, converted to USD at each day''s FX rate.', N'1.1', N'Data office', '2026-09-01', 14),
 (N'fee_rate', N'Fees (% of value)', N'%', N'percent',
  N'Fees in the period as a share of the average market value.',
  N'CAST(SUM(Fees) / NULLIF(AVG(MarketValue), 0) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Fees in the period divided by the average daily USD market value over the period (not annualised).', N'1.1', N'Performance & analytics', '2026-09-01', 15),
 (N'weight', N'Weight', N'%', N'percent',
  N'Share of total market value at the period-end holdings snapshot. Needs a holdings grouping.',
  NULL,
  N'CAST(SUM(CAST(MarketValue AS FLOAT)) / NULLIF(SUM(SUM(CAST(MarketValue AS FLOAT))) OVER (PARTITION BY Series), 0) AS DECIMAL(12,8))', 1, 0,
  N'USD market value of the group divided by the total of the rows in scope, from the month-end snapshot on or before the period end. With look-through, structured products are split into their components.', N'1.1', N'Data office', '2026-09-01', 16),
 (N'growth_index', N'Portfolio growth (index)', N'↗', N'index',
  N'Growth of 100 invested at the start of the period, by month or quarter. Needs a Month or Quarter group-by.',
  N'EXP(SUM(LOG(1.0 + DailyReturn))) - 1',
  NULL, 1, 1,
  N'Time-weighted growth chained month by month from 100 on the day before the period.', N'1.1', N'Performance & analytics', '2026-09-01', 17),
 (N'benchmark_index', N'Benchmark growth (index)', N'↗', N'index',
  N'Growth of 100 in the benchmark over the same days. Needs a Month or Quarter group-by.',
  N'EXP(SUM(LOG(1.0 + BenchmarkReturn))) - 1',
  NULL, 1, 1,
  N'Benchmark growth chained month by month from 100 on the day before the period.', N'1.1', N'Performance & analytics', '2026-09-01', 18),
 (N'volatility', N'Volatility', N'σ', N'percent',
  N'Annualised standard deviation of daily returns.',
  N'CAST(STDEV(DailyReturn) * SQRT(252.0) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Sample standard deviation of daily USD returns times the square root of 252.', N'1.1', N'Performance & analytics', '2026-09-01', 19),
 (N'sharpe_ratio', N'Sharpe ratio', N'#', N'ratio',
  N'Annualised return above a 2% risk-free rate, divided by volatility.',
  N'CAST(((POWER(EXP(SUM(LOG(1.0 + DailyReturn))), 252.0 / COUNT(DailyReturn)) - 1) - 0.02) / NULLIF(STDEV(DailyReturn) * SQRT(252.0), 0) AS DECIMAL(12,4))',
  NULL, 0, 0,
  N'(Annualised return - 2% risk-free rate) / annualised volatility. Return annualised over 252 business days a year.', N'1.1', N'Performance & analytics', '2026-09-01', 20),
 (N'max_drawdown', N'Maximum drawdown', N'%', N'percent',
  N'Largest fall from a previous peak during the period.',
  N'CAST(MIN(EXP(CumLog - IIF(RunMax > 0, RunMax, 0)) - 1) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Largest percentage fall of the time-weighted growth index from its running peak (starting at 100) within the period.', N'1.1', N'Performance & analytics', '2026-09-01', 21),
 (N'tracking_error', N'Tracking error', N'σ', N'percent',
  N'Annualised standard deviation of the daily difference between portfolio and benchmark returns.',
  N'CAST(STDEV(DailyReturn - BenchmarkReturn) * SQRT(252.0) AS DECIMAL(12,8))',
  NULL, 0, 0,
  N'Sample standard deviation of daily (portfolio - benchmark) returns times the square root of 252.', N'1.1', N'Performance & analytics', '2026-09-01', 22),
 (N'information_ratio', N'Information ratio', N'#', N'ratio',
  N'Annualised excess return divided by tracking error.',
  N'CAST(((POWER(EXP(SUM(LOG(1.0 + DailyReturn))), 252.0 / COUNT(DailyReturn)) - 1) - (POWER(EXP(SUM(LOG(1.0 + BenchmarkReturn))), 252.0 / COUNT(BenchmarkReturn)) - 1)) / NULLIF(STDEV(DailyReturn - BenchmarkReturn) * SQRT(252.0), 0) AS DECIMAL(12,4))',
  NULL, 0, 0,
  N'(Annualised portfolio return - annualised benchmark return) / tracking error.', N'1.1', N'Performance & analytics', '2026-09-01', 23);

