INSERT studio.BlockPreset (PresetKey, Label, Icon, Description, BlockJson, SortOrder) VALUES
 (N'performance_summary', N'Performance summary', N'▦', N'KPI cards: market value, TWR, MWR, benchmark and excess return for the report period.',
  N'{"type":"data","display":"kpi","width":"full","title":"Performance summary","measures":["market_value","return_twr","mwr","benchmark_return","excess_return"],"groupBy":[],"period":"report","compare":"none","topN":null,"sort":"value_desc"}', 1),
 (N'indexed_growth', N'Indexed growth', N'📈', N'Line chart of portfolio vs benchmark growth of 100, by month.',
  N'{"type":"data","display":"line","width":"full","title":"Indexed growth · {Base date} = 100","measures":["growth_index","benchmark_index"],"groupBy":["month"],"period":"report","compare":"none","topN":null,"sort":"label_asc","labels":{"growth_index":"Portfolio","benchmark_index":"Benchmark"}}', 2),
 (N'return_by_period', N'Return by period', N'☷', N'Table of TWR, MWR, benchmark and relative return for the quarter, half, year, 3 years and since inception.',
  N'{"type":"data","display":"table","width":"full","title":"Return by period","measures":["return_twr","mwr","benchmark_return","excess_return"],"groupBy":["return_period"],"period":"report","compare":"none","topN":null,"sort":"value_desc","labels":{"return_twr":"Portfolio (TWR)","mwr":"Money-weighted","benchmark_return":"Benchmark","excess_return":"Relative"}}', 3),
 (N'risk_characteristics', N'Risk characteristics', N'σ', N'List of 3-year volatility, Sharpe ratio, maximum drawdown, tracking error and information ratio.',
  N'{"type":"data","display":"list","width":"full","title":"Risk characteristics · 3 years","measures":["volatility","sharpe_ratio","max_drawdown","tracking_error","information_ratio"],"groupBy":[],"period":"3y","compare":"none","topN":null,"sort":"value_desc"}', 4),
 (N'twr_vs_mwr', N'TWR vs MWR', N'⇄', N'KPI cards comparing the time-weighted and money-weighted return with the period''s net flows.',
  N'{"type":"data","display":"kpi","width":"full","title":"Time- and money-weighted return","measures":["return_twr","mwr","net_flows"],"groupBy":[],"period":"report","compare":"none","topN":null,"sort":"value_desc"}', 5),
 (N'account_breakdown', N'Return by account', N'☰', N'Table of value, TWR, MWR and contribution to return for each account.',
  N'{"type":"data","display":"table","width":"full","title":"Return by account","measures":["market_value","return_twr","mwr","contribution"],"groupBy":["portfolio"],"period":"report","compare":"none","topN":null,"sort":"value_desc","labels":{"return_twr":"Portfolio (TWR)","mwr":"Money-weighted","benchmark_return":"Benchmark","excess_return":"Relative"}}', 6),
 (N'entity_breakdown', N'Return by entity', N'⚇', N'Table of value, TWR, MWR and contribution for each client entity in the household.',
