INSERT studio.ReportVersion (ReportId, VersionNo, Status, DefinitionJson, PreviewPassed, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, SubmittedBy, SubmittedOn, ReviewedBy, ReviewedOn, ReviewComment) VALUES
 (@Id, 1, N'Published',
  N'{"scope":"Client","preview":{"householdId":"1","clientId":null,"portfolioCode":null,"fromDate":"2025-01-01","toDate":"2025-12-31"},"pages":[{"id":"p01","title":"Cover","group":"Front matter","locked":true,"sectionLabel":"","heading":"{Report name}","layout":"cover","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p01b1","type":"text","variant":"header","width":"full","title":"{Client}","text":"{Portfolio}\nReporting period {From date} – {To date}\nPrepared {Run date}"}]},{"id":"p02","title":"Investor letter","group":"Front matter","locked":false,"sectionLabel":"Introduction","heading":"A letter to you","layout":"letter","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p02b1","type":"text","variant":"body","width":"full","title":"","text":"Dear {Client},\n\nThank you for the trust you continue to place in us. This review covers {Period}, from {From date} to {To date}, for your {Portfolio}.\n\nThe pages that follow show how your investments performed against their benchmark, how your assets are allocated, what changed during the period and the costs you paid. Every figure is taken directly from our systems of record.\n\nYours sincerely,\nYour wealth management team","narrative":"The body of a short personal letter to the client (no address block): thank them, summarise the period''s return against the benchmark, the change in value and the net flows, and mention one or two of the material movements. 120-180 words. End with ''Yours sincerely,'' and ''Your wealth management team'' on separate lines."},{"id":"p02b2","type":"data","display":"kpi","width":"full","title":"At a glance","measures":["market_value","return_twr","mwr","net_flows"],"groupBy":[],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p03","title":"Portfolio snapshot","group":"Front matter","locked":false,"sectionLabel":"Section one","heading":"Portfolio snapshot","layout":"kpi","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p03b1","type":"data","display":"kpi","width":"full","title":"Key figures","measures":["market_value","investment_gain","return_twr","benchmark_return","excess_return","net_flows"],"groupBy":[],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p03b2","type":"data","display":"pie","width":"half","title":"Asset allocation","measures":["weight"],"groupBy":["asset_class"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p03b3","type":"data","display":"pie","width":"half","title":"Regional exposure","measures":["weight"],"groupBy":["region"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p04","title":"Performance","group":"Portfolio pages","locked":false,"sectionLabel":"Section two","heading":"Performance overview","layout":"kpi","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p04b1","type":"data","display":"line","width":"full","title":"Indexed growth · {Base date} = 100","measures":["growth_index","benchmark_index"],"groupBy":["month"],"period":"report","compare":"none","topN":null,"sort":"label_asc","labels":{"growth_index":"Portfolio","benchmark_index":"Benchmark"}},{"id":"p04b2","type":"data","display":"table","width":"full","title":"Return by period","measures":["return_twr","mwr","benchmark_return","excess_return"],"groupBy":["return_period"],"period":"report","compare":"none","topN":null,"sort":"value_desc","labels":{"return_twr":"Portfolio (TWR)","mwr":"Money-weighted","benchmark_return":"Benchmark","excess_return":"Relative"}},{"id":"p04b3","type":"data","display":"list","width":"half","title":"Risk characteristics · 3 years","measures":["volatility","sharpe_ratio","max_drawdown","tracking_error","information_ratio"],"groupBy":[],"period":"3y","compare":"none","topN":null,"sort":"value_desc"},{"id":"p04b4","type":"text","variant":"body","width":"half","title":"About these figures","text":"Your portfolio''s return is shown both time-weighted, which measures the investment decisions, and money-weighted, which also reflects the timing of your deposits and withdrawals.","narrative":"Two short paragraphs on performance over the period: the time-weighted return against the benchmark, the money-weighted return and why it differs (timing and size of flows), and how risk behaved. 80-130 words."},{"id":"p04b5","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"PERF_GENERAL"}]},{"id":"p05","title":"Household & entities","group":"Portfolio pages","locked":false,"sectionLabel":"Section three","heading":"Your household at a glance","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p05b1","type":"data","display":"table","width":"full","title":"By entity","measures":["market_value","return_twr","mwr","contribution"],"groupBy":["client"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p05b2","type":"data","display":"table","width":"full","title":"By account","measures":["market_value","return_twr","benchmark_return","mwr","contribution"],"groupBy":["portfolio"],"period":"report","compare":"none","topN":null,"sort":"value_desc","labels":{"return_twr":"Portfolio (TWR)","mwr":"Money-weighted","benchmark_return":"Benchmark","excess_return":"Relative"}},{"id":"p05b3","type":"data","display":"bar","width":"full","title":"Contribution to return by account","measures":["contribution"],"groupBy":["portfolio"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p06","title":"Allocation by asset class","group":"Portfolio pages","locked":false,"sectionLabel":"Section four","heading":"Allocation by asset class","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p06b1","type":"data","display":"bar","width":"full","title":"Weight by asset class · this year vs last year","measures":["weight"],"groupBy":["asset_class"],"period":"report","compare":"previous_year","topN":null,"sort":"value_desc"},{"id":"p06b2","type":"data","display":"table","width":"full","title":"Holdings by asset class","measures":["market_value","weight"],"groupBy":["asset_class"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p07","title":"Asset allocation","group":"Portfolio pages","locked":false,"sectionLabel":"Section five","heading":"Asset allocation","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p07b1","type":"data","display":"pie","width":"half","title":"Asset allocation","measures":["weight"],"groupBy":["asset_class"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p07b2","type":"data","display":"table","width":"half","title":"Allocation by asset class and sector","measures":["weight"],"groupBy":["asset_class","sector"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p08","title":"Sector & geography","group":"Portfolio pages","locked":false,"sectionLabel":"Section six","heading":"Sector & geography","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p08b1","type":"data","display":"bar","width":"half","title":"Sector weights","measures":["weight"],"groupBy":["sector"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p08b2","type":"data","display":"pie","width":"half","title":"Regional exposure","measures":["weight"],"groupBy":["region"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p09","title":"Principal holdings","group":"Portfolio pages","locked":false,"sectionLabel":"Section seven","heading":"Principal holdings","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p09b1","type":"data","display":"table","width":"full","title":"Top 10 holdings","measures":["market_value","weight"],"groupBy":["security","asset_class","region"],"period":"report","compare":"none","topN":10,"sort":"value_desc"}]},{"id":"p10","title":"Structured products","group":"Portfolio pages","locked":false,"sectionLabel":"Section eight","heading":"Structured products: a look-through view","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p10b1","type":"data","display":"pie","width":"half","title":"Asset allocation · looking through structured products","measures":["weight"],"groupBy":["lookthrough_asset_class"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p10b2","type":"data","display":"table","width":"half","title":"Direct holdings and structured products","measures":["market_value","weight"],"groupBy":["holding_type"],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p10b3","type":"text","variant":"body","width":"full","title":"","text":"Structured products combine a bond-like part, which provides capital protection or income, with an option that gives exposure to an equity index. The look-through view splits each product into these parts.","narrative":"One short paragraph explaining what the look-through view shows: how the structured products split into bond-like and equity-like exposure, and what that means for the household''s overall allocation. 50-90 words."}],"condition":"StructuredProducts"},{"id":"p11","title":"Currency","group":"Portfolio pages","locked":false,"sectionLabel":"Section nine","heading":"Currency effects","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p11b1","type":"data","display":"table","width":"full","title":"Return by account currency","measures":["market_value","return_local","fx_effect","return_twr"],"groupBy":["account_currency"],"period":"report","compare":"none","topN":null,"sort":"value_desc","labels":{"return_local":"Local currency","fx_effect":"Currency effect","return_twr":"In US dollars"}},{"id":"p11b2","type":"text","variant":"body","width":"full","title":"","text":"Some of your accounts are held in currencies other than the US dollar. Their returns in US dollars include the effect of exchange-rate movements.","narrative":"One short paragraph explaining how currency movements affected the accounts held in currencies other than the US dollar, comparing their local-currency and US-dollar returns. 50-90 words."}],"condition":"MultiCurrency"},{"id":"p12","title":"Key changes","group":"Portfolio pages","locked":false,"sectionLabel":"Section ten","heading":"Key changes in the period","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p12b1","type":"data","display":"bar","width":"full","title":"Sector weights · this year vs last year","measures":["weight"],"groupBy":["sector"],"period":"report","compare":"previous_year","topN":8,"sort":"value_desc"},{"id":"p12b2","type":"data","display":"table","width":"full","title":"Cash flows by quarter","measures":["deposits","withdrawals","net_flows"],"groupBy":["quarter"],"period":"report","compare":"none","topN":null,"sort":"label_asc"},{"id":"p12b3","type":"text","variant":"body","width":"full","title":"","text":"The allocation was kept in line with your agreed strategy during the period.","narrative":"One short paragraph on what changed in the period: allocation shifts, large flows and accounts that stood out. 60-110 words."}]},{"id":"p13","title":"Commentary","group":"Commentary & close","locked":false,"sectionLabel":"Section eleven","heading":"Market commentary","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p13b1","type":"text","variant":"body","width":"full","title":"","text":"Global markets were shaped by the path of interest rates, resilient corporate earnings and periods of geopolitical uncertainty. Diversification across asset classes and regions helped to smooth returns, while bond holdings provided income and stability.\n\nOur house view is set by the investment committee and is the same for every client."}]},{"id":"p14","title":"Strategic outlook","group":"Commentary & close","locked":false,"sectionLabel":"Section twelve","heading":"Strategic outlook","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p14b1","type":"text","variant":"body","width":"full","title":"","text":"We expect growth to moderate and inflation to continue easing, which should support both equities and high-quality bonds. We remain selective, favouring companies with strong balance sheets and durable earnings, and will continue to rebalance portfolios towards their strategic allocation."}]},{"id":"p15","title":"Costs and charges","group":"Commentary & close","locked":false,"sectionLabel":"Section thirteen","heading":"Costs and charges","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p15b1","type":"data","display":"kpi","width":"full","title":"Charges in the period","measures":["fees","fee_rate"],"groupBy":[],"period":"report","compare":"none","topN":null,"sort":"value_desc"},{"id":"p15b2","type":"data","display":"bar","width":"full","title":"Fees by month","measures":["fees"],"groupBy":["month"],"period":"report","compare":"none","topN":null,"sort":"label_asc"}]},{"id":"p16","title":"Charges by account","group":"Commentary & close","locked":false,"sectionLabel":"Section fourteen","heading":"Charges by account","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p16b1","type":"data","display":"table","width":"full","title":"Fees by account","measures":["fees","fee_rate","market_value"],"groupBy":["portfolio"],"period":"report","compare":"none","topN":null,"sort":"value_desc"}]},{"id":"p17","title":"Disclosures","group":"Commentary & close","locked":true,"sectionLabel":"Disclosures","heading":"Important information","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p17b1","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"PERF_GENERAL"},{"id":"p17b2","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"METHODOLOGY"},{"id":"p17b3","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"ILLUSTRATIVE"},{"id":"p17b4","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"FX_RISK","condition":"MultiCurrency"},{"id":"p17b5","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"SPL_RISK","condition":"StructuredProducts"},{"id":"p17b6","type":"disclaimer","width":"full","title":"","text":"","disclosureCode":"ADVISORY","condition":"Advisory"}]},{"id":"p18","title":"Closing","group":"Commentary & close","locked":true,"sectionLabel":"","heading":"Thank you","layout":"standard","style":{"typeface":"serif","bodySize":10,"lineHeight":1.5},"blocks":[{"id":"p18b1","type":"text","variant":"body","width":"full","title":"","text":"Thank you for choosing us to look after your wealth. If your circumstances, objectives or attitude to risk have changed, please let your wealth manager know so that we can review your mandate.\n\nYour next scheduled review is shown in your client profile. We are available at any time to discuss this report."}]}]}',
  1, N'priya.shah', '2026-09-01T09:00:00', N'priya.shah', '2026-09-01T09:30:00', N'priya.shah', '2026-09-01T09:30:00', N'james.mokoena', '2026-09-02T11:00:00', N'Seeded version.');

